class MultipleResponseRandom {

  public interface Service {

    @Mock
    @MockResponse(body = "smith.json")
    @MockResponse(body = "doe.json")
    @MockRandom
    @GET("/")
    Call<MultipleResponseRandom.User> getUser();
  }

  static class User {

    @Json(name = "name")
    String name;

    @Json(name = "surname")
    String surname;

    @Override
    public String toString() {
      return "User{"
        + "name='" + name + '\''
        + ", surname='" + surname + '\''
        + '}';
    }
  }

  public static void main(String[] args) throws IOException {

    Retrofit retrofit = new Retrofit.Builder()
      .baseUrl("https://www.google.com")
      .addConverterFactory(MoshiConverterFactory.create())
      .build();

    Retromock retromock = new Retromock.Builder()
      .retrofit(retrofit)
      .defaultBodyFactory(new ResourceBodyFactory())
      .build();

    MultipleResponseRandom.Service service = retromock.create(MultipleResponseRandom.Service.class);

    System.out.println(service.getUser().execute().body());
    System.out.println(service.getUser().execute().body());
    System.out.println(service.getUser().execute().body());
    System.out.println(service.getUser().execute().body());
  }
}

