                ConnectionListeningFuture<T, E, M> future = new ConnectionListeningFuture<>(cmd);
                client.connectAsClient(future, handshake, host, port);
                future.waitAndRun();
                // logger.debug("Connection available and active, command now being run inline.");
            }
            return;
        }
    }

