//
// Examples
// [1, 1, 2] ==> 2
// [17, 17, 17, 17, 3, 17] ==> 3
function stray(numbers) {
    if (numbers[0] !== numbers[1] && numbers[0] !== numbers[2]) {
        return numbers[0];
    }

    for (let i = 1; i < numbers.length; i++) {
        if (numbers[i] !== numbers[0]) {
            return numbers[i];
        }
