    public SimulationAnimationEffecter(PuppetView readAnimView) {
        this.puppetView = readAnimView;
        pointPaint = new Paint();
        pointPaint.setColor(Color.RED);
        pointPaint.setTextSize(25);

        a = new FPoint(-1, -1);
