        float rA = a.y - h.y;
        float rB = h.x - a.x;
        float rC = a.x * h.y - h.x * a.y;
        rPathAShadowDis = Math.abs((rA * i.x + rB * i.y + rC) / (float) Math.hypot(rA, rB));
    }

    protected class ScrollRunnable implements Runnable {
        @Override
        public void run() {
            puppetView.reset();
            curlAnimationRunning = false;
            invalidate();
        }
    }
}

