    request(url, requestOptions, function(err, response, body) {
        if (err) {
            callback(err);
        } else if (response.statusCode == 200) {
            callback(null, body);
        } else {
            return callback(new Error("Unable to download JSON. Code " + response.statusCode));
        }
    });
