	def lowest_common_supertype(self, f1, f2, fn):
		""" Returns the common supertype of F1 and F2. Could be used for metaphor, etc. """
		if f1 == f2:
			return f1
		elif fn.subtype(f1, f2):
			return f2
		elif fn.subtype(f2, f1):
			return f1
