		"""Looks up the given token in the loaded embeddings."""
		key = token

		if key not in self.data:
			key = self.strip_outer(token)	# Try removing < and >
		if key not in self.data:
			key = f"<{token}>"				# Try wrapping in < and >
		if key not in self.data:
