		@param {Function} fpCallback 순서가 되었을 때 실행 할 함수

		@return {this}

		@example
			oMorph.pushCall(function() {
				alert('애니메이션이 시작될꺼임');
			}).pushAnimate(3000,
				elFoo, {
					'@left' : '300px',
					'scrollTop' : 100
