    private static final Predicate<String> QUALITY_PARAM_FILTERING_PREDICATE = input -> !Quality.QUALITY_SOURCE_PARAMETER_NAME.equals(input) && !Quality.QUALITY_PARAMETER_NAME.equals(input);

    private MediaTypes() {
        throw new AssertionError("Instantiation not allowed.");
    }

