        byte blue = (byte) curCodeGroup.blueCode.readSymbol(lsbBitReader);
        byte alpha = (byte) curCodeGroup.alphaCode.readSymbol(lsbBitReader);

        rgba[0] = red;
        rgba[1] = (byte) code;
        rgba[2] = blue;
        rgba[3] = alpha;
        raster.setDataElements(x, y, rgba);

